    printf("Expected:   ");
    for (int i = 0; i < rar5_signature_size; i++) {
        printf("%02x ", expected[i]);
    }
    printf("\n");
    printf("Match: %d\n", memcmp(rar5_signature, expected, rar5_signature_size) == 0);

    return 0;
}
EOF
